      "qualname": "arrow/arrow.py::Arrow.span",
      "source": "def span(self, frame, count=1, bounds="[)", exact=False, week_start=1):
    if not 1 <= week_start <= 7:
        raise ValueError("week_start argument must be between 1 and 7.")
    util.validate_bounds(bounds)
    fa, fr, rs = self._get_frames(frame)
    a = "day" if fa == "week" else "month" if fa == "quarter" else fa
    fl = self
    if not exact:
        i = self._ATTRS.index(a)
        frames = self._ATTRS[:i+1]
        vals = [getattr(self, f) for f in frames] + [1]*max(0, 3-len(frames))
        fl = self.__class__(*vals, tzinfo=self.tzinfo)
        if fa == "week":
            d = 7 if week_start > self.isoweekday() else 0
            fl = fl.shift(days=-(self.isoweekday() - week_start) - d)
        elif fa == "quarter":
            fl = fl.shift(months=-((self.month - 1) % 3))
    cl = fl.shift(**{fr: count * rs})
    if bounds[0] == "(":
        fl = fl.shift(microseconds=+1)
    if bounds[1] == ")":
        cl = cl.shift(microseconds=-1)
    return fl, cl"
    },
    {
      "qualname": "arrow/arrow.py::Arrow.span_range",
      "source": "@classmethod
def span_range(cls, frame, start, end, tz=None, limit=None, bounds="[)", exact=False):
    tzinfo = cls._get_tzinfo(start.tzinfo if tz is None else tz)
    start = cls.fromdatetime(start, tzinfo).span(frame, exact=exact)[0]
    end = cls.fromdatetime(end, tzinfo)
    _range = cls.range(frame, start, end, tz, limit)
    if not exact:
        for r in _range:
            yield r.span(frame, bounds=bounds, exact=exact)
    else:
        for r in _range:
            floor, ceil = r.span(frame, bounds=bounds, exact=exact)
            if ceil > end:
                ceil = end
                if bounds[1] == ")":
                    ceil += relativedelta(microseconds=-1)
            if floor == end:
                break
            elif floor + relativedelta(microseconds=-1) == end:
                break
            yield floor, ceil"
    },
    {
      "qualname": "arrow/arrow.py::Arrow.dehumanize",
      "source": "def dehumanize(self, timestring, locale="en_us"):
    lo = locales.get_locale(locale)
    nl = locale.lower().replace("_", "-")
    if nl not in DEHUMANIZE_LOCALES:
        raise ValueError(f"Dehumanize does not currently support the {locale} locale, please consider making a contribution to add support for this locale.")
    ct = self.fromdatetime(self._datetime)
    toi = {k:0 for k in ["seconds","minutes","hours","days","weeks","months","years"]}
    uv = {k:False for k in ["now","seconds","minutes","hours","days","weeks","months","years"]}
    np = re.compile(r"\d+")
    for unit, fmt in lo.timeframes.items():
        cv = 0
        s = str(fmt).format(r"\d+")
        m = re.compile(fr"{s}").search(timestring)
        if not m:
            continue
        ms = m.group()
        nm = np.search(ms)
        cv = 1 if not nm else int(nm.group())
        if unit == "now":
            uv[unit] = True
            continue
        tu = str(unit) + ("s" if str(unit)[-1] != "s" else "")
        toi[tu] = cv
        uv[tu] = True
    if not any(uv.values()):
        raise ValueError("Input string not valid. Note: Some locales do not support the week granulairty in Arrow. If you are attempting to use the week granularity on an unsupported locale, this could be the cause of this error.")
    fs = lo.future.format(".*")
    fp = re.compile(fr"^{fs}$")
    fpm = fp.findall(timestring)
    ps = lo.past.format(".*")
    pp = re.compile(fr"^{ps}$")
    ppm = pp.findall(timestring)
    if ppm:
        sv = -1
    elif fpm:
        sv = 1
    elif uv["now"]:
        sv = 0
    else:
        raise ValueError("Invalid input String. String does not contain any relative time information. String should either represent a time in the future or a time in the past. Ex: \"in 5 seconds\" or \"5 seconds ago\".")
    tc = {k: sv * v for k, v in toi.items()}
    return ct.shift(**tc)"
